@startuml

class Employee {
  + name : string
  + socialSecurityNumber : string
}

class Planner extends Employee {
  + username : string
  + password : string
}

class AdministrativeStaff extends Employee {
  + username : string
  + password : string
  + fieldOfActivity : string
}

class Customer {
  + name : string
  + billingAddress : string
}

class PartnerCompany {
  + name : string
  + address : string
}

class Vehicle {
  + licensePlate : string
  + mileage : int
}

class RefrigeratedTruck extends Vehicle {}

class SmallVan extends Vehicle {}

class LoadingPlatform extends Vehicle {}

class BoxTruck extends Vehicle {}

class RepairShop {
  + name : string
  + address : string
}

class Repair {
  + duration : string
  + cost : double
}

class Order {
  + packageSize : string
  + comment : string
  + startTime : datetime
  + finishTime : datetime
  + pickUpAddress : string
  + deliveryAddress : string
}

Employee "1" -- "*" Repair : takes vehicle to
Repair "*" -- "1" Vehicle
Repair "*" -- "1" RepairShop

Driver "1" -- "*" Order : is assigned to
Driver "1" -- "*" Order : completes
Order "*" -- "1" Vehicle : uses
Order "*" -- "1" Planner : assigned by
Order "*" -- "1" Customer : client
Order "*" -- "0..1" PartnerCompany : placed with
Order "*" -- "0..1" AdministrativeStaff : placed with

@enduml

